// EDIT THIS LIST with the real category URLs you want indexed.
// The original workflow only scraped one page (shop-desktop-ram).
// Add every category page from technova-demo.com you want the bot to know about.

const categories = [
  "   https://www.technova-demo.com/pc-components/shop-desktop-ram",

  ];

return categories.map(url => ({ json: { url } }));

 const item = $input.first();
const html = item.json.data || item.json.body || '';

if (!html) {
  return [];
}

// Remove scripts, styles, comments, then strip tags.
// NOTE: the old version also stripped all non-ASCII characters, which
// deleted Bengali text and the Taka (৳) symbol from the knowledge base.
// That has been removed here so Bengali product info survives.
const clean = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 8000);

if (!clean || clean.length < 100) {
  return [];
}

let sourceUrl = 'technova-demo.com';
try {
  sourceUrl = $('Loop Over Category URLs').item.json.url || sourceUrl;
} catch (e) {}

// Stock status বের করা - scraped content-এ "Stock : In Stock" বা
// "Stock : Out of Stock" প্যাটার্ন থেকে
let stockStatus = 'unknown';
const stockMatch = clean.match(/Stock\s*:\s*(In Stock|Out of Stock)/i);
if (stockMatch) {
  stockStatus = stockMatch[1].toLowerCase().includes('out') ? 'out_of_stock' : 'in_stock';
}

return [{
  json: {
    pageContent: clean,
    metadata: {
      source: sourceUrl,
      stock_status: stockStatus
    }
  }
}];

const item = $input.first().json;
const msg = item.message || {};
let route = 'text';
if (msg.voice) route = 'voice';
else if (msg.photo && msg.photo.length > 0) route = 'photo';
return [{ json: { ...item, route } }];

 const item = $input.first();
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = binaryBuffer.toString('base64');
const mimeType = item.binary.data.mimeType || 'audio/ogg';

const promptText = 'Transcribe this voice message to text exactly as spoken. Output ONLY the transcript, no commentary or translation, in the same language/script it was spoken in (Bengali, Banglish, or English).';

const body = {
  contents: [{
    parts: [
      { text: promptText },
      { inline_data: { mime_type: mimeType, data: base64 } }
    ]
  }]
};

return [{ json: { geminiBody: body } }];

const res = $input.first().json;
let text = '';
try {
  text = res.candidates[0].content.parts[0].text.trim();
} catch (e) {
  text = '';
}
if (!text) {
  text = '[Voice message could not be transcribed]';
}
return [{ json: { userMessage: text, route: 'voice' } }];

const item = $input.first();
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = binaryBuffer.toString('base64');
const mimeType = item.binary.data.mimeType || 'image/jpeg';
const customerCaption = (item.json.message && item.json.message.caption) || '';

let promptText = 'This is a screenshot sent by a customer of TechNova, a computer hardware shop in Bangladesh. If it shows a product listing or webpage, extract the product name, key specs, and price. If it shows an order confirmation, payment, or delivery status, extract the order ID, amount, and status shown. If it is an error message or app screen, describe exactly what it says. Respond in plain text only, in the same language visible in the image where possible.';

if (customerCaption) {
  promptText += ` The customer wrote this message along with the screenshot: "${customerCaption}". Keep this in mind as their actual question or intent while describing the screenshot.`;
}

const body = {
  contents: [{
    parts: [
      { text: promptText },
      { inline_data: { mime_type: mimeType, data: base64 } }
    ]
  }]
};

return [{ json: { geminiBody: body, customerCaption } }];

const res = $input.first().json;
const customerCaption = res.customerCaption || '';
let text = '';
try {
  text = res.candidates[0].content.parts[0].text.trim();
} catch (e) {
  text = '';
}
if (!text) {
  text = '[Screenshot could not be analyzed]';
}

let userMessage;
if (customerCaption) {
  userMessage = `${customerCaption}\n\n[Screenshot context: ${text}]`;
} else {
  userMessage = '[Customer sent a screenshot] ' + text;
}

return [{ json: { userMessage, route: 'photo' } }];
